/**
 * Envío transaccional de facturas desde el Gmail conectado por cada usuario.
 * La operación está limitada a facturas de la empresa activa y registra el éxito
 * únicamente después de que Gmail confirme el envío.
 */
import { createClientFromRequest } from 'npm:@base44/sdk@0.8.38';

const GMAIL_CONNECTOR_ID = '6a1b49be4d83894815de65a2';
const MAX_ATTACHMENT_BYTES = 10 * 1024 * 1024;
const MAX_TOTAL_ATTACHMENT_BYTES = 20 * 1024 * 1024;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function bytesToBase64(bytes) {
  let binary = '';
  const chunkSize = 0x8000;
  for (let i = 0; i < bytes.length; i += chunkSize) {
    binary += String.fromCharCode(...bytes.subarray(i, Math.min(i + chunkSize, bytes.length)));
  }
  return btoa(binary);
}

function encodeHeader(value) {
  return `=?UTF-8?B?${bytesToBase64(new TextEncoder().encode(String(value || '')))}?=`;
}

function base64Lines(value) {
  return value.match(/.{1,76}/g)?.join('\r\n') || '';
}

function safeFilename(value) {
  return String(value || 'documento.pdf').replace(/[\r\n"]/g, '_').slice(0, 160);
}

function isSafeRemoteUrl(value) {
  try {
    const url = new URL(value);
    return url.protocol === 'https:'
      && url.hostname === 'base44.app'
      && !url.username && !url.password && !url.port && !url.hash
      && url.pathname.startsWith('/api/apps/6a00fec50cc522a74ddde4b2/files/mp/');
  } catch {
    return false;
  }
}


// Downloads never follow an arbitrary redirect or buffer an unbounded body.
function isSafeDownloadUrl(value) {
  if (isSafeRemoteUrl(value)) return true;
  try {
    const url = new URL(value);
    return url.protocol === 'https:' && url.hostname === 'media.base44.com'
      && !url.username && !url.password && !url.port && !url.hash
      && ['public', 'private'].some(kind =>
        url.pathname.startsWith('/files/' + kind + '/6a00fec50cc522a74ddde4b2/'));
  } catch { return false; }
}

async function downloadInvoicePdf(initialUrl) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 20000);
  let reader;
  try {
    let url = initialUrl;
    for (let hop = 0; hop <= 3; hop++) {
      if (!isSafeDownloadUrl(url)) throw Object.assign(new Error('Destino del adjunto no autorizado.'), { status: 400 });
      const response = await fetch(url, { redirect: 'manual', signal: controller.signal });
      if ([301, 302, 303, 307, 308].includes(response.status)) {
        await response.body?.cancel();
        const location = response.headers.get('location');
        if (!location || hop === 3) throw Object.assign(new Error('Redirección de adjunto no válida.'), { status: 502 });
        url = new URL(location, url).toString();
        continue;
      }
      if (!response.ok) {
        await response.body?.cancel();
        throw Object.assign(new Error('No se pudo descargar el PDF adjunto.'), { status: 502 });
      }
      const declaredLength = response.headers.get('content-length');
      if (declaredLength !== null && (!/^\d+$/.test(declaredLength) || Number(declaredLength) > MAX_ATTACHMENT_BYTES)) {
        await response.body?.cancel();
        throw Object.assign(new Error('El PDF supera el límite de 10 MB.'), { status: 413 });
      }
      reader = response.body?.getReader();
      if (!reader) throw Object.assign(new Error('El PDF adjunto está vacío.'), { status: 400 });
      const chunks = [];
      let size = 0;
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        size += value.byteLength;
        if (size > MAX_ATTACHMENT_BYTES) throw Object.assign(new Error('El PDF supera el límite de 10 MB.'), { status: 413 });
        chunks.push(value);
      }
      if (!size) throw Object.assign(new Error('El PDF adjunto está vacío.'), { status: 400 });
      const bytes = new Uint8Array(size);
      let offset = 0;
      for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
      if (String.fromCharCode(...bytes.subarray(0, 5)) !== '%PDF-') {
        throw Object.assign(new Error('El adjunto no es un PDF válido.'), { status: 415 });
      }
      return bytes;
    }
    throw Object.assign(new Error('Redirección de adjunto no válida.'), { status: 502 });
  } catch (error) {
    if (controller.signal.aborted) throw Object.assign(new Error('La descarga del PDF ha tardado demasiado. No se ha enviado el correo.'), { status: 504 });
    throw error;
  } finally {
    clearTimeout(timeout);
    await reader?.cancel().catch(() => {});
    reader?.releaseLock();
    controller.abort();
  }
}

function normalizeEmails(input, label, required = false) {
  const values = (Array.isArray(input) ? input : input ? [input] : [])
    .map(value => String(value || '').trim().toLowerCase())
    .filter(Boolean);
  const unique = [...new Set(values)];
  if (required && unique.length === 0) throw Object.assign(new Error(`Añade al menos un destinatario en ${label}.`), { status: 400 });
  if (unique.length > 10) throw Object.assign(new Error(`Demasiados destinatarios en ${label}.`), { status: 400 });
  const invalid = unique.filter(value => !EMAIL_RE.test(value));
  if (invalid.length) throw Object.assign(new Error(`Dirección no válida en ${label}: ${invalid.join(', ')}`), { status: 400 });
  return unique;
}

async function getGmailConnection(base44) {
  try {
    // El cliente se crea desde la petición autenticada: Base44 resuelve aquí
    // la conexión OAuth del usuario actual, nunca un buzón global compartido.
    const connection = await base44.asServiceRole.connectors.getCurrentAppUserConnection(GMAIL_CONNECTOR_ID);
    return connection?.accessToken ? connection : null;
  } catch {
    return null;
  }
}

async function getConnectedEmail(connection) {
  const configured = connection?.connectionConfig?.email
    || connection?.connectionConfig?.emailAddress
    || connection?.connectionConfig?.accountEmail;
  if (configured && EMAIL_RE.test(configured)) return configured;
  // Fallback sin gmail.metadata: el endpoint OAuth2 funciona con userinfo.email
  // aunque el proveedor no haya emitido un flujo OpenID completo.
  const response = await fetch('https://www.googleapis.com/oauth2/v2/userinfo', {
    headers: { Authorization: `Bearer ${connection.accessToken}` },
  }).catch(() => null);
  if (!response?.ok) return '';
  const userinfo = await response.json().catch(() => ({}));
  return EMAIL_RE.test(userinfo.email || '') ? userinfo.email : '';
}

async function loadAttachments(input, allowedUrl, requireInvoicePdf) {
  const attachments = Array.isArray(input) ? input : [];
  if (requireInvoicePdf && attachments.length !== 1) {
    throw Object.assign(new Error('La factura debe enviarse con un único PDF adjunto.'), { status: 400 });
  }
  if (!requireInvoicePdf && attachments.length > 0) {
    throw Object.assign(new Error('Este tipo de documento no admite adjuntos en este flujo.'), { status: 400 });
  }
  const loaded = [];
  let totalSize = 0;
  for (const item of attachments) {
    const url = typeof item === 'string' ? item : item?.url;
    if (!url || url !== allowedUrl || !isSafeRemoteUrl(url)) {
      throw Object.assign(new Error('El adjunto no coincide con el PDF de la factura.'), { status: 400 });
    }
    const bytes = await downloadInvoicePdf(url);
    totalSize += bytes.byteLength;
    if (totalSize > MAX_TOTAL_ATTACHMENT_BYTES) throw new Error('Los adjuntos superan el límite total de 20 MB.');
    loaded.push({
      name: safeFilename(typeof item === 'string' ? url.split('/').pop() : item.name),
      mimeType: 'application/pdf',
      content: bytesToBase64(bytes),
    });
  }
  return loaded;
}

function buildRawMessage({ from, to, cc, bcc, subject, html, attachments }) {
  const headers = [
    `From: ${from}`,
    `To: ${to.join(', ')}`,
  ];
  if (cc.length) headers.push(`Cc: ${cc.join(', ')}`);
  if (bcc.length) headers.push(`Bcc: ${bcc.join(', ')}`);
  headers.push(`Subject: ${encodeHeader(subject)}`, 'MIME-Version: 1.0');
  const boundary = `taxea_${crypto.randomUUID()}`;
  const htmlBase64 = base64Lines(bytesToBase64(new TextEncoder().encode(html)));
  headers.push(`Content-Type: multipart/mixed; boundary="${boundary}"`, '');
  const parts = [
    `--${boundary}`,
    'Content-Type: text/html; charset=UTF-8',
    'Content-Transfer-Encoding: base64',
    '',
    htmlBase64,
  ];
  for (const attachment of attachments) {
    parts.push(
      `--${boundary}`,
      `Content-Type: ${attachment.mimeType}; name="${attachment.name}"`,
      'Content-Transfer-Encoding: base64',
      `Content-Disposition: attachment; filename="${attachment.name}"`,
      '',
      base64Lines(attachment.content),
    );
  }
  parts.push(`--${boundary}--`, '');
  return [...headers, ...parts].join('\r\n');
}

function toBase64Url(raw) {
  return bytesToBase64(new TextEncoder().encode(raw))
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

Deno.serve(async (req) => {
  let base44;
  let user;
  let invoice;
  let companyId;
  let body = {};
  try {
    if (req.method !== 'POST') return Response.json({ error: 'Método no permitido.' }, { status: 405 });
    base44 = createClientFromRequest(req);
    user = await base44.auth.me().catch(() => null);
    if (!user?.id) return Response.json({ error: 'Unauthorized' }, { status: 401 });
    if (user.is_deleted || ['eliminado', 'bloqueado', 'suspendido'].includes(user.status)
      || user.accountAccessStatus === 'suspended') return Response.json({ error: 'Acceso al portal suspendido.', code: 'ACCOUNT_DISABLED' }, { status: 403 });
    body = await req.json().catch(() => ({}));
    const connection = await getGmailConnection(base44);

    if (body.action === 'status') {
      if (!connection) return Response.json({ ok: true, connected: false, error: 'gmail_not_connected' });
      const email = await getConnectedEmail(connection);
      return Response.json({
        ok: true,
        connected: true,
        email,
        identity_available: Boolean(email),
        scope: 'user',
      });
    }

    const isAdmin = user.role === 'admin' || user.role === 'super_admin';
    companyId = body.company_id || user.data?.company_id;
    if (!companyId) return Response.json({ error: 'La empresa activa no es válida.' }, { status: 403 });
    const company = await base44.asServiceRole.entities.Company.get(companyId).catch(() => null);
    const email = String(user.email || '').trim().toLowerCase();
    const isMember = company && email && (
      String(company.owner_email || '').trim().toLowerCase() === email
      || (company.usuarios_autorizados || []).some(value => String(value || '').trim().toLowerCase() === email)
    );
    if (!company || company.activa === false || (!isAdmin && !isMember)) {
      return Response.json({ error: 'La empresa activa no es válida.' }, { status: 403 });
    }
    if (body.invoice_id) {
      invoice = await base44.asServiceRole.entities.Invoice.get(body.invoice_id).catch(() => null);
      if (!invoice || invoice.company_id !== companyId) {
        return Response.json({ error: 'Factura no encontrada en la empresa activa.' }, { status: 404 });
      }
      if (invoice.anulada) return Response.json({ error: 'No se puede enviar una factura anulada.' }, { status: 409 });
      if (invoice.fiscal_review_status === 'pendiente_revision' || ['FISCAL_ADVISOR_REVIEW_PHASE1', 'FISCAL_POSTING_ERROR'].includes(invoice.accounting_migration_hold_reason)) return Response.json({ error: 'La factura requiere validación fiscal del asesor antes de enviarse.' }, { status: 409 });
    } else {
      const entityName = body.document_type === 'quote' ? 'Quote' : body.document_type === 'proforma' ? 'Proforma' : '';
      if (!entityName || !body.document_id) {
        return Response.json({ error: 'El documento de origen no es válido.' }, { status: 400 });
      }
      const document = await base44.asServiceRole.entities[entityName].get(body.document_id).catch(() => null);
      if (!document || document.company_id !== companyId) {
        return Response.json({ error: 'Documento no encontrado en la empresa activa.' }, { status: 404 });
      }
    }
    if (!connection) {
      return Response.json({
        error: 'gmail_not_connected',
        message: 'Conecta tu cuenta Gmail para enviar desde tu propio correo.',
      }, { status: 403 });
    }

    const to = normalizeEmails(body.to, 'Para', true);
    const cc = normalizeEmails(body.cc, 'CC');
    const bcc = normalizeEmails(body.bcc, 'CCO');
    const subject = String(body.subject || '').trim().slice(0, 240);
    const html = String(body.html || '');
    if (!subject || !html || html.length > 250_000) {
      return Response.json({ error: 'El asunto o el contenido del email no son válidos.' }, { status: 400 });
    }
    const allowedInvoicePdfUrl = invoice?.qr_url && invoice?.tipo === 'emitida'
      ? invoice?.qr_pdf_url
      : invoice?.archivo_url;
    if (invoice && !allowedInvoicePdfUrl) return Response.json({ error: 'La factura no tiene un PDF válido preparado para este envío.' }, { status: 409 });
    let validPublicLink = false;
    try {
      const publicLink = new URL(String(body.public_invoice_url || ''));
      validPublicLink = publicLink.origin === 'https://taxeaportal.com'
        && !publicLink.username && !publicLink.password && !publicLink.search && !publicLink.hash
        && publicLink.pathname === `/public/invoice/${invoice?.public_token}`;
    } catch { /* No outbound message with an untrusted invoice link. */ }
    if (invoice && (!invoice.public_token || !validPublicLink)) {
      return Response.json({ error: 'El enlace público de la factura no está validado.' }, { status: 409 });
    }

    const idempotencyKey = String(body.idempotency_key || '').trim().slice(0, 100);
    if (invoice && idempotencyKey) {
      const duplicate = await base44.asServiceRole.entities.InvoiceEmailLog.filter({
        company_id: companyId,
        invoice_id: invoice.id,
        idempotency_key: idempotencyKey,
        delivery_status: 'enviada',
      }, '-sent_at', 1);
      if (duplicate?.[0]) {
        return Response.json({
          ok: true,
          duplicate: true,
          id: duplicate[0].provider_message_id || '',
          thread_id: duplicate[0].provider_thread_id || '',
          via: 'gmail',
          from: duplicate[0].sender_email || '',
          attachment_count: duplicate[0].attachments?.length || 0,
        });
      }
    }

    const attachments = await loadAttachments(body.attachments, allowedInvoicePdfUrl, Boolean(invoice));
    const connectedEmail = await getConnectedEmail(connection);
    if (!connectedEmail) {
      return Response.json({ error: 'gmail_identity_unavailable', message: 'No se pudo identificar el buzón Gmail conectado.' }, { status: 502 });
    }
    const senderName = String(body.from_name || 'Taxea Portal').replace(/[\r\n"]/g, '').slice(0, 100);
    const raw = buildRawMessage({
      from: `"${senderName}" <${connectedEmail}>`,
      to,
      cc,
      bcc,
      subject,
      html,
      attachments,
    });
    const gmailResponse = await fetch('https://gmail.googleapis.com/gmail/v1/users/me/messages/send', {
      method: 'POST',
      headers: { Authorization: `Bearer ${connection.accessToken}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ raw: toBase64Url(raw) }),
    });
    const gmailData = await gmailResponse.json().catch(() => ({}));
    if (!gmailResponse.ok) {
      const gmailMessage = gmailData.error?.message || 'Gmail no ha aceptado el envío.';
      const gmailReasons = Array.isArray(gmailData.error?.errors)
        ? gmailData.error.errors.map(item => item?.reason).filter(Boolean)
        : [];
      const apiDisabled = gmailReasons.includes('accessNotConfigured')
        || /Gmail API has not been used|Gmail API.*disabled/i.test(gmailMessage);
      const authorizationExpired = gmailResponse.status === 401
        || gmailReasons.some(reason => ['authError', 'invalidCredentials'].includes(reason))
        || (gmailResponse.status === 403 && (
          gmailReasons.includes('insufficientPermissions')
          || /insufficient authentication scopes/i.test(gmailMessage)
        ));
      throw Object.assign(new Error(gmailMessage), {
        status: authorizationExpired ? 403 : apiDisabled ? 503 : 502,
        code: authorizationExpired
          ? 'gmail_authorization_expired'
          : apiDisabled
            ? 'gmail_api_not_enabled'
            : 'gmail_send_failed',
      });
    }

    const now = new Date().toISOString();
    let trackingWarning = '';
    try {
      if (invoice) await base44.asServiceRole.entities.InvoiceEmailLog.create({
        invoice_id: invoice.id,
        company_id: companyId,
        to: to.join(', '),
        cc: cc.join(', '),
        bcc: bcc.join(', '),
        subject,
        body: html,
        template_id: String(body.template_id || 'envio_factura').slice(0, 80),
        attachments: [allowedInvoicePdfUrl],
        public_invoice_url: body.public_invoice_url,
        pdf_attachment_name: attachments[0]?.name || '',
        sent_at: now,
        sent_by: user.full_name || user.email || 'Usuario',
        sender_email: connectedEmail,
        provider_message_id: gmailData.id || '',
        provider_thread_id: gmailData.threadId || '',
        idempotency_key: idempotencyKey || '',
        delivery_status: 'enviada',
        to_was_manual: Boolean(body.to_was_manual),
        error_message: null,
      });
      if (invoice) await base44.asServiceRole.entities.Invoice.update(invoice.id, { estado_envio: 'enviada' });
      if (invoice) await base44.asServiceRole.entities.InvoiceTimelineEvent.create({
        invoice_id: invoice.id,
        company_id: companyId,
        event_type: 'email_enviado',
        event_label: 'Email enviado',
        event_detail: `Enviado a ${to.join(', ')} · PDF adjunto · Gmail ${connectedEmail}`,
        created_at: now,
        created_by: user.full_name || user.email || 'Usuario',
        origin: 'manual',
      });
    } catch (trackingError) {
      trackingWarning = 'El correo se envió, pero parte de la trazabilidad no pudo guardarse.';
      console.error('[sendEmail] tracking after Gmail success:', trackingError);
    }

    return Response.json({
      ok: true,
      id: gmailData.id,
      thread_id: gmailData.threadId,
      via: 'gmail',
      from: connectedEmail,
      attachment_count: attachments.length,
      warning: trackingWarning || undefined,
    });
  } catch (error) {
    console.error('[sendEmail]', error);
    if (base44 && invoice && companyId) {
      await base44.asServiceRole.entities.InvoiceEmailLog.create({
        invoice_id: invoice.id,
        company_id: companyId,
        to: Array.isArray(body.to) ? body.to.join(', ') : String(body.to || ''),
        subject: String(body.subject || '').slice(0, 240),
        sent_at: new Date().toISOString(),
        sent_by: user?.full_name || user?.email || 'Usuario',
        delivery_status: 'error_envio',
        error_message: String(error?.message || 'Error desconocido').slice(0, 500),
      }).catch(() => {});
    }
    return Response.json({ error: error?.code || 'send_failed', message: error?.message || 'Error interno.' }, { status: error?.status || 500 });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.44';

const DEFAULTS = {
  userMinute: 4,
  userDay: 40,
  userMonth: 300,
  userTokensDay: 80000,
  adminMinute: 20,
  adminDay: 200,
  adminMonth: 2000,
  adminTokensDay: 500000,
  maxPromptChars: 24000,
  maxFiles: 3,
  maxSchemaChars: 20000,
};

function utcKeys(now = new Date()) {
  const iso = now.toISOString();
  return {
    minuteKey: iso.slice(0, 16),
    dayKey: iso.slice(0, 10),
    monthKey: iso.slice(0, 7),
  };
}

function estimatedTokens(text: string) {
  return Math.max(1, Math.ceil(text.length / 4));
}

function usageCount(events: any[]) {
  return (events || []).filter((event) => event.status !== 'blocked').length;
}

function tokenCount(events: any[]) {
  return (events || [])
    .filter((event) => event.status !== 'blocked')
    .reduce((sum, event) => sum + Number(event.estimatedInputTokens || 0), 0);
}

function safeModel(value: unknown) {
  if (value == null || value === '') return undefined;
  if (typeof value !== 'string' || !/^[a-zA-Z0-9_.-]{1,64}$/.test(value)) {
    throw new Error('Modelo de IA no válido');
  }
  return value;
}

function validateFileUrls(value: unknown, maxFiles: number) {
  if (value == null) return undefined;
  if (!Array.isArray(value) || value.length > maxFiles) throw new Error('Demasiados archivos adjuntos');
  return value.map((raw) => {
    if (typeof raw !== 'string' || raw.length > 2048) throw new Error('URL de archivo no válida');
    const url = new URL(raw);
    const appId = '6a00fec50cc522a74ddde4b2';
    const appFile = url.hostname === 'base44.app'
      && url.pathname.startsWith('/api/apps/' + appId + '/files/mp/');
    const mediaFile = url.hostname === 'media.base44.com'
      && ['public', 'private'].some(kind => url.pathname.startsWith('/files/' + kind + '/' + appId + '/'));
    if (url.protocol !== 'https:' || url.username || url.password || url.port || url.hash || (!appFile && !mediaFile)) {
      throw new Error('URL de archivo no válido: utiliza documentos de Taxea en HTTPS');
    }
    return url.toString();
  });
}

Deno.serve(async (req) => {
  let eventId: string | undefined;
  try {
    if (req.method !== 'POST') return Response.json({ error: 'Método no permitido' }, { status: 405 });
    const base44 = createClientFromRequest(req);
    const user = await base44.auth.me().catch(() => null);
    if (!user) return Response.json({ error: 'No autenticado' }, { status: 401 });
    if (user.is_deleted || ['eliminado', 'bloqueado', 'suspendido'].includes(user.status)
      || user.accountAccessStatus === 'suspended') return Response.json({ error: 'Acceso al portal suspendido.', code: 'ACCOUNT_DISABLED' }, { status: 403 });

    const body = await req.json().catch(() => ({}));
    const isAdmin = ['admin', 'super_admin'].includes(user.role);
    const limits = isAdmin
      ? {
          minute: DEFAULTS.adminMinute,
          day: DEFAULTS.adminDay,
          month: DEFAULTS.adminMonth,
          tokensDay: DEFAULTS.adminTokensDay,
        }
      : {
          minute: DEFAULTS.userMinute,
          day: DEFAULTS.userDay,
          month: DEFAULTS.userMonth,
          tokensDay: DEFAULTS.userTokensDay,
        };

    const maxPromptChars = DEFAULTS.maxPromptChars;
    const maxFiles = DEFAULTS.maxFiles;
    const maxSchemaChars = DEFAULTS.maxSchemaChars;
    const keys = utcKeys();
    const userId = String(user.id);

    const [minuteEvents, dayEvents, monthEvents] = await Promise.all([
      base44.asServiceRole.entities.AIUsageEvent.filter({ userId, minuteKey: keys.minuteKey }),
      base44.asServiceRole.entities.AIUsageEvent.filter({ userId, dayKey: keys.dayKey }),
      base44.asServiceRole.entities.AIUsageEvent.filter({ userId, monthKey: keys.monthKey }),
    ]);

    const snapshot = {
      minute: usageCount(minuteEvents),
      day: usageCount(dayEvents),
      month: usageCount(monthEvents),
      tokensDay: tokenCount(dayEvents),
    };

    if (body.action === 'status') {
      return Response.json({
        limits,
        used: snapshot,
        remaining: {
          minute: Math.max(0, limits.minute - snapshot.minute),
          day: Math.max(0, limits.day - snapshot.day),
          month: Math.max(0, limits.month - snapshot.month),
          tokensDay: Math.max(0, limits.tokensDay - snapshot.tokensDay),
        },
      });
    }

    const prompt = typeof body.prompt === 'string' ? body.prompt.trim() : '';
    if (!prompt) return Response.json({ error: 'El prompt es obligatorio' }, { status: 400 });
    if (prompt.length > maxPromptChars) {
      return Response.json({ error: 'La solicitud supera el tamaño máximo permitido' }, { status: 413 });
    }

    const fileUrls = validateFileUrls(body.file_urls, maxFiles);
    const schema = body.response_json_schema;
    if (schema != null && (typeof schema !== 'object' || JSON.stringify(schema).length > maxSchemaChars)) {
      return Response.json({ error: 'El esquema de respuesta no es válido o es demasiado grande' }, { status: 400 });
    }

    const inputTokens = estimatedTokens(prompt) + (fileUrls?.length || 0) * 1000;
    const exceeded =
      snapshot.minute >= limits.minute ? 'minute'
      : snapshot.day >= limits.day ? 'day'
      : snapshot.month >= limits.month ? 'month'
      : snapshot.tokensDay + inputTokens > limits.tokensDay ? 'tokensDay'
      : null;

    if (exceeded) {
      await base44.asServiceRole.entities.AIUsageEvent.create({
        userId,
        userEmail: user.email || '',
        companyId: user.data?.company_id || '',
        ...keys,
        requestId: crypto.randomUUID(),
        operation: 'llm',
        status: 'blocked',
        promptChars: prompt.length,
        estimatedInputTokens: inputTokens,
        internetContext: body.add_context_from_internet === true,
        fileCount: fileUrls?.length || 0,
        errorCode: `limit_${exceeded}`,
        completedAt: new Date().toISOString(),
      });
      const retryAfterSeconds = exceeded === 'minute' ? 60 : exceeded === 'day' || exceeded === 'tokensDay' ? 3600 : 86400;
      return Response.json(
        { error: 'Has alcanzado temporalmente el límite de uso de IA. Inténtalo más tarde.', code: `AI_LIMIT_${exceeded.toUpperCase()}` },
        { status: 429, headers: { 'Retry-After': String(retryAfterSeconds) } },
      );
    }

    const model = safeModel(body.model);
    const event = await base44.asServiceRole.entities.AIUsageEvent.create({
      userId,
      userEmail: user.email || '',
      companyId: user.data?.company_id || '',
      ...keys,
      requestId: crypto.randomUUID(),
      operation: 'llm',
      status: 'reserved',
      model: model || '',
      promptChars: prompt.length,
      estimatedInputTokens: inputTokens,
      internetContext: body.add_context_from_internet === true,
      fileCount: fileUrls?.length || 0,
    });
    eventId = event.id;

    const params: Record<string, unknown> = { prompt };
    if (body.add_context_from_internet === true) params.add_context_from_internet = true;
    if (schema != null) params.response_json_schema = schema;
    if (fileUrls) params.file_urls = fileUrls;
    if (model) params.model = model;

    const result = await base44.asServiceRole.integrations.Core.InvokeLLM(params);
    const outputChars = typeof result === 'string' ? result.length : JSON.stringify(result ?? '').length;
    await base44.asServiceRole.entities.AIUsageEvent.update(event.id, {
      status: 'success',
      estimatedOutputTokens: estimatedTokens('x'.repeat(Math.min(outputChars, 200000))),
      completedAt: new Date().toISOString(),
    });

    return Response.json({ result });
  } catch (error) {
    console.error('[invokeLimitedLLM] Error:', error);
    if (eventId) {
      try {
        const retryClient = createClientFromRequest(req);
        await retryClient.asServiceRole.entities.AIUsageEvent.update(eventId, {
          status: 'error',
          errorCode: 'provider_or_internal_error',
          completedAt: new Date().toISOString(),
        });
      } catch (_) {
        // La respuesta de error principal no debe quedar bloqueada por la auditoría.
      }
    }
    const message = error instanceof Error && /no válido|Demasiados|HTTPS/.test(error.message)
      ? error.message
      : 'No se pudo completar la solicitud de IA';
    return Response.json({ error: message }, { status: /no válido|Demasiados|HTTPS/.test(message) ? 400 : 500 });
  }
});

