  qr_pdf_url: qrPdfUrl, public_token: 'test-token',
};
const logs = [];
const requestedFiles = [];
let gmailCalls = 0;
const entities = {
  Company: { async get(id) { return id === 'company-a' ? { id, owner_email: 'sender@example.test', usuarios_autorizados: [] } : null; } },
  Invoice: {
